package com.example.th7.data;
import com.example.th7.model.BatterySnapshot;import com.example.th7.model.ChargingSession;import org.junit.Test;import java.util.Arrays;import java.util.Collections;import static org.junit.Assert.*;
public class BatteryStatisticsCalculatorTest {
 @Test public void filtersSamplesAndCalculatesLevelAndVoltage(){BatterySnapshot a=new BatterySnapshot(20,-1,0,4f,null,null,null,-1,1000),b=new BatterySnapshot(80,-1,0,null,null,null,null,-1,2000),x=new BatterySnapshot(100,-1,0,99f,null,null,null,-1,500);BatteryStatisticsCalculator.Summary s=BatteryStatisticsCalculator.calculate(Arrays.asList(x,a,b),Collections.emptyList(),1000,2000);assertEquals(20,s.min);assertEquals(80,s.max);assertEquals(50f,s.average,0.01f);assertEquals(4f,s.averageVoltage,0.01f);}
 @Test public void emptySummaryDoesNotInventMeasurements(){BatteryStatisticsCalculator.Summary s=BatteryStatisticsCalculator.calculate(Collections.emptyList(),Collections.emptyList(),0,10);assertFalse(s.hasLevel());assertTrue(Float.isNaN(s.averageVoltage));assertEquals(0,s.sessionCount);}
 @Test public void countsCompletedAndOpenSessions(){ChargingSession a=new ChargingSession("1","x","2m",20,30,"USB",1000,121000),b=new ChargingSession("2","x","open",30,40,"AC",2000,0);BatteryStatisticsCalculator.Summary s=BatteryStatisticsCalculator.calculate(Collections.emptyList(),Arrays.asList(a,b),0,2000);assertEquals(2,s.sessionCount);assertEquals(1,s.completedSessions);assertEquals(2,s.durationMinutes);}
 @Test public void ignoresFutureSamplesAndInvalidSessionDurations(){BatterySnapshot past=new BatterySnapshot(40,-1,0,null,null,null,null,-1,1000),future=new BatterySnapshot(90,-1,0,4f,null,null,null,-1,3000);ChargingSession unobserved=new ChargingSession("3","x","duration unknown",40,60,"USB",500,2500,false),badClock=new ChargingSession("4","x","invalid range",40,60,"USB",1500,1400,true);BatteryStatisticsCalculator.Summary s=BatteryStatisticsCalculator.calculate(Arrays.asList(past,future),Arrays.asList(unobserved,badClock),0,2000);assertEquals(40,s.min);assertEquals(40,s.max);assertEquals(40f,s.average,0.01f);assertTrue(Float.isNaN(s.averageVoltage));assertEquals(2,s.sessionCount);assertEquals(0,s.completedSessions);}
}
